package in.tucor.api.buyer; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="buyer_payments") public class BuyerPayment {@Id public UUID id;@Column(name="public_id") public String publicId;@Column(name="buyer_id") public UUID buyerId;@Column(name="order_id") public UUID orderId;public BigDecimal amount;public String status;@Column(name="due_date") public LocalDate dueDate;@Column(name="settled_date") public LocalDate settledDate;public String reference;@Column(name="invoice_number") public String invoiceNumber;@Column(name="created_at") public Instant createdAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}}